    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    cn = [0.0 for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if r[i] is not None and r[j] is not None and r[i] > 1e-8 and r[j] > 1e-8:
                u = d / (1.25 * (r[i] + r[j]))
                cn[i] += occ[j] * exp(-(u ** 6))
    valid = [i for i in range(n) if r[i] is not None and r[i] > 1e-8 and occ[i] > 0]
    weight = sum(occ[i] for i in valid)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * cn[i] for i in valid) / weight
    if mean <= 1e-12:
        return 0.0
    variance = sum(occ[i] * (cn[i] - mean) ** 2 for i in valid) / weight
    return sqrt(max(variance, 0.0)) / mean

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    elements = [a.get('element') for a in sites]
    counts = {}
    for i in range(n):
        if elements[i] is not None and occ[i] > 0:
            counts[elements[i]] = counts.get(elements[i], 0.0) + occ[i]
    population = sum(counts.values())
    if population <= 0:
        return 0.0
    nearest = [inf for a in sites]
    neighbors = s.get('neighbors') or []
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    unlike = 0.0
    for b in neighbors:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and isfinite(nearest[i]):
            if elements[i] is not None and elements[j] is not None:
                w = occ[i] * occ[j] * exp(-((d / (1.25 * nearest[i])) ** 6))
                total += w
                if elements[i] != elements[j]:
                    unlike += w
    expected = 1.0 - sum((x / population) ** 2 for x in counts.values())
    return unlike / total - expected if total > 1e-12 else 0.0

def feature(s):
