    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    en = [(p.get(a.get('element')) or {}).get('eneg') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    total = 0.0
    internal = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if en[i] is not None and en[i] >= 2.5 and en[j] is not None and r[i] is not None and r[j] is not None and r[i] > 1e-8 and r[j] > 1e-8:
                u = d / (1.25 * (r[i] + r[j]))
                w = occ[i] * occ[j] * exp(-(u ** 6))
                total += w
                if en[j] >= 2.5:
                    internal += w
    return internal / total if total > 1e-12 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    mu = []
    gap = []
    r = []
    for a in sites:
        prop = p.get(a.get('element')) or {}
        ie = prop.get('first_ionization_energy_eV')
        ea = prop.get('electron_affinity_eV')
        r.append(prop.get('covalent_radius_A'))
        if ie is not None and ea is not None and ie - ea > 1e-8:
            mu.append(0.5 * (ie + ea))
            gap.append(ie - ea)
        else:
            mu.append(None)
            gap.append(None)
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if mu[i] is not None and mu[j] is not None and r[i] is not None and r[j] is not None and r[i] > 1e-8 and r[j] > 1e-8:
                u = d / (1.25 * (r[i] + r[j]))
                w = occ[i] * occ[j] * exp(-(u ** 6))
                total += w * (mu[i] - mu[j]) ** 2 / (gap[i] + gap[j])
    weight = sum(occ[i] for i in range(n) if mu[i] is not None and r[i] is not None and r[i] > 1e-8)
    return total / (2.0 * weight) if weight > 0 else 0.0
